create extension if not exists pgcrypto;

create type public.app_role as enum ('customer','admin','editor','fulfilment','finance');
create type public.business_model as enum ('affiliate','resale','sourcing');
create type public.product_availability as enum ('affiliate','local_inventory','pre_order','sourcing_only');
create type public.order_status as enum ('awaiting_payment','payment_verification','payment_confirmed','procurement_approved','ordered_from_supplier','supplier_processing','dispatched','international_transit','customs_processing','local_courier','ready_for_collection','delivered','cancelled','refund_pending','refunded','exception');

create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles (user_id uuid references auth.users on delete cascade, role app_role not null, primary key(user_id, role));
create table public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, label text not null, recipient_name text not null, phone text not null, address_line text not null, city text not null, county text, is_default boolean not null default false, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, published boolean not null default false, created_at timestamptz not null default now());
create table public.collections (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, image_url text, published boolean not null default false, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', brand text, category_id uuid references public.categories, availability product_availability not null, business_model business_model not null, currency text not null default 'KES', original_price numeric(14,2), local_selling_price numeric(14,2), estimated_shipping numeric(14,2), estimated_duties numeric(14,2), additional_fees numeric(14,2), margin numeric(14,2), source_url text, affiliate_tracking_url text, publication_status text not null default 'draft' check (publication_status in ('draft','review','published','archived')), verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, name text not null, sku text, attributes jsonb not null default '{}', price numeric(14,2), available boolean not null default false);
create table public.product_media (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, storage_path text not null, alt_text text not null default '', sort_order int not null default 0);
create table public.product_sources (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, marketplace text not null, source_url text not null, permitted_access_method text not null, last_checked_at timestamptz);
create table public.suppliers (id uuid primary key default gen_random_uuid(), name text not null, country text, supplier_type text, marketplace text, verification_status text not null default 'unverified', notes text, created_at timestamptz not null default now());
create table public.supplier_products (supplier_id uuid references public.suppliers on delete cascade, product_id uuid references public.products on delete cascade, minimum_order_quantity int, lead_time_days int, primary key(supplier_id, product_id));
create table public.affiliate_partners (id uuid primary key default gen_random_uuid(), name text not null, programme_status text not null default 'pending_approval', disclosure_text text, commission_rate numeric(8,4), terms_url text, created_at timestamptz not null default now());
create table public.affiliate_links (id uuid primary key default gen_random_uuid(), partner_id uuid not null references public.affiliate_partners on delete cascade, product_id uuid references public.products on delete cascade, tracking_url text not null, campaign text, active boolean not null default false);
create table public.affiliate_click_events (id uuid primary key default gen_random_uuid(), affiliate_link_id uuid not null references public.affiliate_links on delete cascade, user_id uuid references auth.users, session_id text, created_at timestamptz not null default now());
create table public.sourcing_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, product_url text not null, quantity int not null check(quantity > 0), variant text, notes text, status text not null default 'submitted', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.sourcing_request_media (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.sourcing_requests on delete cascade, storage_path text not null, created_at timestamptz not null default now());
create table public.quotations (id uuid primary key default gen_random_uuid(), quotation_number text not null unique, sourcing_request_id uuid not null references public.sourcing_requests, user_id uuid not null references auth.users, currency text not null default 'KES', exchange_rate numeric(14,6), shipping numeric(14,2) not null default 0, duties numeric(14,2) not null default 0, taxes numeric(14,2) not null default 0, service_fee numeric(14,2) not null default 0, markup numeric(14,2) not null default 0, discount numeric(14,2) not null default 0, total numeric(14,2) not null default 0, delivery_window text, expiry_date date, admin_notes text, status text not null default 'draft', accepted_at timestamptz, created_at timestamptz not null default now());
create table public.quotation_items (id uuid primary key default gen_random_uuid(), quotation_id uuid not null references public.quotations on delete cascade, description text not null, quantity int not null check(quantity > 0), unit_amount numeric(14,2) not null);
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique, user_id uuid not null references auth.users, business_model business_model not null, status order_status not null default 'awaiting_payment', currency text not null default 'KES', total numeric(14,2) not null default 0, address_id uuid references public.addresses, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, product_id uuid references public.products, description text not null, quantity int not null check(quantity > 0), unit_amount numeric(14,2) not null);
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders, quotation_id uuid references public.quotations, user_id uuid not null references auth.users, provider text not null, transaction_reference text, amount numeric(14,2) not null, currency text not null default 'KES', status text not null default 'pending', provider_payload jsonb, verified_by uuid references auth.users, verified_at timestamptz, idempotency_key text unique, created_at timestamptz not null default now());
create table public.refunds (id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments, amount numeric(14,2) not null, reason text not null, status text not null default 'pending', created_at timestamptz not null default now());
create table public.fulfilment_events (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, status order_status not null, message text not null, customer_visible boolean not null default true, created_by uuid references auth.users, created_at timestamptz not null default now());
create table public.wishlists (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users on delete cascade, created_at timestamptz not null default now());
create table public.wishlist_items (wishlist_id uuid references public.wishlists on delete cascade, product_id uuid references public.products on delete cascade, created_at timestamptz not null default now(), primary key(wishlist_id, product_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, title text not null, body text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.support_cases (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, subject text not null, message text not null, status text not null default 'open', created_at timestamptz not null default now());
create table public.editorial_articles (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, excerpt text, body text not null, published boolean not null default false, created_at timestamptz not null default now());
create table public.operating_expenses (id uuid primary key default gen_random_uuid(), description text not null, amount numeric(14,2) not null, currency text not null default 'KES', category text not null, incurred_on date not null, created_by uuid references auth.users);
create table public.exchange_rate_snapshots (id uuid primary key default gen_random_uuid(), base_currency text not null, quote_currency text not null, rate numeric(14,6) not null, source text not null, captured_at timestamptz not null default now());
create table public.integration_settings (id uuid primary key default gen_random_uuid(), provider text not null unique, enabled boolean not null default false, public_config jsonb not null default '{}', updated_at timestamptz not null default now());
create table public.admin_audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users, action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());

create or replace function public.has_role(required_role app_role) returns boolean language sql security definer set search_path = public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=required_role) $$;
create or replace function public.is_admin() returns boolean language sql security definer set search_path = public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role in ('admin','editor','fulfilment','finance')) $$;

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.addresses enable row level security; alter table public.products enable row level security; alter table public.sourcing_requests enable row level security; alter table public.sourcing_request_media enable row level security; alter table public.quotations enable row level security; alter table public.quotation_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.refunds enable row level security; alter table public.fulfilment_events enable row level security; alter table public.wishlists enable row level security; alter table public.wishlist_items enable row level security; alter table public.notifications enable row level security; alter table public.support_cases enable row level security; alter table public.admin_audit_logs enable row level security;
create policy "public products" on public.products for select using (publication_status='published' or public.is_admin());
create policy "own profiles" on public.profiles for all using (id=auth.uid() or public.is_admin()) with check (id=auth.uid() or public.is_admin());
create policy "own addresses" on public.addresses for all using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin());
create policy "own sourcing" on public.sourcing_requests for all using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin());
create policy "own quotations" on public.quotations for select using (user_id=auth.uid() or public.is_admin());
create policy "own quote items" on public.quotation_items for select using (exists(select 1 from public.quotations q where q.id=quotation_id and (q.user_id=auth.uid() or public.is_admin())));
create policy "own orders" on public.orders for select using (user_id=auth.uid() or public.is_admin());
create policy "own order items" on public.order_items for select using (exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin())));
create policy "own payments" on public.payments for select using (user_id=auth.uid() or public.is_admin());
create policy "own notifications" on public.notifications for all using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin());
create policy "own wishlist" on public.wishlists for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own wishlist items" on public.wishlist_items for all using (exists(select 1 from public.wishlists w where w.id=wishlist_id and w.user_id=auth.uid())) with check (exists(select 1 from public.wishlists w where w.id=wishlist_id and w.user_id=auth.uid()));
create policy "own support" on public.support_cases for all using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin());
create policy "admin fulfilment" on public.fulfilment_events for select using (customer_visible and exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()) or public.is_admin());
create policy "admin products" on public.products for insert with check (public.is_admin()); create policy "admin products update" on public.products for update using (public.is_admin());
create policy "admin audit" on public.admin_audit_logs for insert with check (public.is_admin());

create index products_status_idx on public.products(publication_status); create index products_category_idx on public.products(category_id); create index sourcing_user_idx on public.sourcing_requests(user_id); create index orders_user_idx on public.orders(user_id); create index fulfilment_order_idx on public.fulfilment_events(order_id, created_at); create index notifications_user_idx on public.notifications(user_id, read_at);
